@import "tailwindcss";
@import "@heroui/styles";
@import "../design/component-theme.css";
@import "../design/layout.css";

:root {
  color: var(--dh-text);
  background: var(--dh-background);
  font-family:
    "Hiragino Sans",
    "Hiragino Kaku Gothic ProN",
    "Yu Gothic UI",
    "Yu Gothic",
    system-ui,
    sans-serif;
}

html,
body,
#root {
  min-height: 100%;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  background: var(--dh-background);
  color: var(--dh-text);
  font-size: var(--dh-type-body);
  line-height: var(--dh-type-line-height-body);
}

a {
  color: inherit;
}

.app-header {
  border-bottom: 1px solid var(--dh-border);
  background: color-mix(in oklch, var(--dh-surface) 92%, var(--dh-accent-soft));
}

.app-header__inner {
  padding-block: var(--dh-space-4);
}

.app-header__eyebrow {
  margin: 0 0 var(--dh-space-1);
  color: var(--dh-text-muted);
  font-size: var(--dh-type-small);
}

.back-link {
  width: fit-content;
}

.detail-actions {
  display: flex;
  gap: var(--dh-space-2);
  flex-wrap: wrap;
  justify-content: flex-end;
}

.drawer-description {
  margin: 0;
  color: var(--dh-text-muted);
}

.detail-list {
  margin: 0;
  display: grid;
  gap: var(--dh-space-4);
}

.detail-row {
  display: grid;
  gap: var(--dh-space-1);
}

.detail-row dt {
  color: var(--dh-text-muted);
  font-size: var(--dh-type-small);
}

.detail-row dd {
  margin: 0;
  white-space: pre-wrap;
}

.empty-state {
  background: var(--dh-surface);
}

.alert-dialog__body {
  display: grid;
  gap: var(--dh-space-4);
}

.detail-section__content {
  display: grid;
  gap: var(--dh-space-4);
}

.collection-toolbar .search-field {
  width: 100%;
  max-width: 16rem;
}

@media (max-width: 767px) {
  .detail-actions {
    width: 100%;
    flex-direction: column;
  }

  .detail-actions > * {
    width: 100%;
  }

  .detail-actions .button {
    width: 100%;
  }

  .collection-toolbar .search-field {
    max-width: none;
  }
}
=====APP=====
import {
  Alert,
  AlertDialog,
  Button,
  Card,
  Chip,
  Description,
  Drawer,
  FieldError,
  Form,
  Input,
  Label,
  Link,
  ListBox,
  SearchField,
  Select,
  Table,
  TextField,
  Toast,
  Toolbar,
  toast,
} from "@heroui/react";
import { useEffect, useId, useState } from "react";
import { HashRouter, Navigate, Route, Routes, useLocation, useNavigate, useParams } from "react-router-dom";
import {
  type CustomerDetail,
  type CustomerStatus,
  type CustomerSummary,
  deleteCustomer,
  getCustomerDetail,
  listCustomerSummaries,
  updateCustomer,
} from "./fixtures";

const DETAIL_DELAY_MS = 120;

const STATUS_OPTIONS: Array<{ id: CustomerStatus; label: CustomerStatus }> = [
  { id: "商談中", label: "商談中" },
  { id: "利用中", label: "利用中" },
  { id: "休眠", label: "休眠" },
];

type CustomerTableColumn = {
  id: "companyName" | "contactName" | "lastContactedAt" | "status";
  label: string;
  width: string;
  minWidth: number;
  align: "start" | "end";
  isRowHeader?: boolean;
  tabular?: boolean;
};

const CUSTOMER_TABLE_COLUMNS: CustomerTableColumn[] = [
  {
    id: "companyName",
    label: "企業名",
    width: "38%",
    minWidth: 240,
    align: "start" as const,
    isRowHeader: true,
  },
  {
    id: "contactName",
    label: "担当者",
    width: "22%",
    minWidth: 160,
    align: "start" as const,
  },
  {
    id: "lastContactedAt",
    label: "最終対応日",
    width: "22%",
    minWidth: 160,
    align: "end" as const,
    tabular: true,
  },
  {
    id: "status",
    label: "ステータス",
    width: "18%",
    minWidth: 128,
    align: "start" as const,
  },
];

const DETAIL_STATE_NAMES = new Set([
  "default",
  "drawer-open",
  "invalid-email",
  "loading",
  "success",
  "failure",
  "delete-confirm",
] as const);

type DetailDemoState =
  | "default"
  | "drawer-open"
  | "invalid-email"
  | "loading"
  | "success"
  | "failure"
  | "delete-confirm";

type EditableCustomerFields = Pick<
  CustomerDetail,
  "companyName" | "contactName" | "email" | "status"
>;

type FormErrors = Partial<Record<keyof EditableCustomerFields, string>>;
type FeedbackTone = "success" | "danger";
type SaveMessage = { tone: FeedbackTone; title: string; description: string };
type DetailViewModel = {
  customer: CustomerDetail | null;
  draft: EditableCustomerFields | null;
  isEditOpen: boolean;
  isDeleteOpen: boolean;
  errors: FormErrors;
  saveMessage: SaveMessage | null;
};

function getCompanyHref(customerId: string, state?: string) {
  return state ? `#/customers/${customerId}?state=${state}` : `#/customers/${customerId}`;
}

function getListHref(state?: string) {
  return state ? `#/customers?state=${state}` : "#/customers";
}

function getStatusVariant(status: CustomerStatus) {
  if (status === "利用中") return "secondary";
  if (status === "商談中") return "primary";
  return "tertiary";
}

function isEmailValid(email: string) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

function toDraft(customer: CustomerDetail): EditableCustomerFields {
  return {
    companyName: customer.companyName,
    contactName: customer.contactName,
    email: customer.email,
    status: customer.status,
  };
}

function toDemoDraft(customer: CustomerDetail): EditableCustomerFields {
  return {
    companyName: `${customer.companyName} CS支援`,
    contactName: `${customer.contactName} 担当`,
    email: "team-success@example.com",
    status: "商談中",
  };
}

function getInitialListItems(listState: string | null) {
  return listState === "empty" ? [] : listCustomerSummaries();
}

function getDetailState(rawState: string | null): DetailDemoState {
  if (rawState && DETAIL_STATE_NAMES.has(rawState as DetailDemoState)) {
    return rawState as DetailDemoState;
  }
  return "default";
}

function getInitialDetailViewModel(customerId: string, detailState: DetailDemoState): DetailViewModel {
  const loadedCustomer = getCustomerDetail(customerId);

  if (!loadedCustomer) {
    return {
      customer: null,
      draft: null,
      isEditOpen: false,
      isDeleteOpen: false,
      errors: {},
      saveMessage: null,
    };
  }

  const nextDraft = toDraft(loadedCustomer);
  const demoDraft = toDemoDraft(loadedCustomer);

  return {
    customer: detailState === "success" ? { ...loadedCustomer, ...demoDraft } : loadedCustomer,
    draft:
      detailState === "drawer-open"
        ? nextDraft
        : detailState === "invalid-email"
          ? { ...demoDraft, email: "invalid-email" }
          : detailState === "loading" || detailState === "failure"
            ? demoDraft
            : nextDraft,
    isEditOpen:
      detailState === "drawer-open" ||
      detailState === "invalid-email" ||
      detailState === "loading" ||
      detailState === "failure",
    isDeleteOpen: detailState === "delete-confirm",
    errors: detailState === "invalid-email" ? { email: "メールアドレスの形式を確認してください。" } : {},
    saveMessage:
      detailState === "success"
        ? {
            tone: "success",
            title: "顧客情報を更新しました",
            description: "変更した会社名、担当者、メールアドレス、ステータスを詳細へ反映しました。",
          }
        : detailState === "failure"
          ? {
              tone: "danger",
              title: "顧客情報を更新できませんでした",
              description: "入力内容を保持したまま再試行できます。",
            }
          : null,
  };
}

function AppHeader() {
  return (
    <header className="app-header">
      <div className="page-shell app-header__inner">
        <div>
          <p className="app-header__eyebrow">営業・CS</p>
          <strong>顧客管理</strong>
        </div>
      </div>
    </header>
  );
}

function useIsNarrowLayout() {
  const getMatches = () => window.matchMedia("(max-width: 767px)").matches;
  const [isNarrow, setIsNarrow] = useState(getMatches);

  useEffect(() => {
    const mediaQuery = window.matchMedia("(max-width: 767px)");
    const handleChange = (event: MediaQueryListEvent) => setIsNarrow(event.matches);

    setIsNarrow(mediaQuery.matches);
    mediaQuery.addEventListener("change", handleChange);

    return () => mediaQuery.removeEventListener("change", handleChange);
  }, []);

  return isNarrow;
}

function PageFeedback({
  title,
  description,
  tone = "success",
}: {
  title: string;
  description: string;
  tone?: FeedbackTone;
}) {
  return (
    <Alert.Root status={tone}>
      <Alert.Content>
        <Alert.Title>{title}</Alert.Title>
        <Alert.Description>{description}</Alert.Description>
      </Alert.Content>
    </Alert.Root>
  );
}

function EmptyState({ title, description }: { title: string; description: string }) {
  return (
    <Card.Root className="empty-state">
      <Card.Header>
        <Card.Title>{title}</Card.Title>
        <Card.Description>{description}</Card.Description>
      </Card.Header>
    </Card.Root>
  );
}

function CustomerSummaryTable({
  items,
  detailState,
  isNarrow,
}: {
  items: CustomerSummary[];
  detailState?: string;
  isNarrow: boolean;
}) {
  return (
    <>
      {isNarrow ? (
        <div className="collection-list-mobile" aria-label="顧客一覧モバイル">
          {items.map((customer) => (
            <Card.Root key={customer.id}>
              <Card.Header>
                <Card.Title>
                  <Link href={getCompanyHref(customer.id, detailState)} className="table-link">
                    {customer.companyName}
                  </Link>
                </Card.Title>

