import "@testing-library/jest-dom/vitest";
import { cleanup, render, screen } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { App } from "./App";
import { resetCustomerRecords } from "./fixtures";

beforeEach(() => {
  resetCustomerRecords();
  Object.defineProperty(window, "matchMedia", {
    writable: true,
    value: (q: string) => ({ matches: false, media: q, onchange: null, addListener() {}, removeListener() {}, addEventListener() {}, removeEventListener() {}, dispatchEvent: () => false }),
  });
  Object.defineProperty(window, "ResizeObserver", { writable: true, value: class { observe() {} unobserve() {} disconnect() {} } });
});
afterEach(() => { cleanup(); window.location.hash = ""; });

describe("states", () => {
  it("default", async () => {
    window.location.hash = "#/customers";
    render(<App />);
    expect(await screen.findByRole("heading", { name: "顧客一覧" })).toBeInTheDocument();
    expect(screen.getAllByRole("row")).toHaveLength(5);
  });
  it("detail default", async () => {
    window.location.hash = "#/customers/customer_northstar";
    render(<App />);
    expect(await screen.findByText("03-1234-5678")).toBeInTheDocument();
    expect(screen.getByText("次回の定例は9月5日。新しい担当者を紹介予定。")).toBeInTheDocument();
  });
  it("loading", async () => {
    window.location.hash = "#/customers/customer_northstar?state=loading";
    render(<App />);
    expect(await screen.findByText("顧客情報を保存しています")).toBeInTheDocument();
    expect(screen.getByRole("button", { name: /保存中/ })).toBeDisabled();
  });
  it("success", async () => {
    window.location.hash = "#/customers/customer_northstar?state=success";
    render(<App />);
    expect(await screen.findByText("顧客情報を保存しました")).toBeInTheDocument();
    expect(screen.getByRole("heading", { name: "株式会社ノーススター CS支援" })).toBeInTheDocument();
  });
  it("invalid-email", async () => {
    window.location.hash = "#/customers/customer_northstar?state=invalid-email";
    render(<App />);
    expect(await screen.findByText("メールアドレスの形式を確認してください。")).toBeInTheDocument();
    expect(screen.getByLabelText("メールアドレス")).toHaveValue("invalid-email");
  });
  it("failure", async () => {
    window.location.hash = "#/customers/customer_northstar?state=failure";
    render(<App />);
    expect(await screen.findByText("顧客情報を保存できませんでした")).toBeInTheDocument();
    expect(screen.getByRole("button", { name: "保存" })).toBeEnabled();
  });
});
EOF
